import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

mean_reduce_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void mean_reduce_kernel(const float* input, float* output, 
                                  int num_outputs, int reduce_size, 
                                  int inner_dim_stride, int outer_dim_stride) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_outputs) return;

    const int outer_idx = idx / outer_dim_stride;
    const int inner_idx = idx % outer_dim_stride;

    float sum = 0.0f;
    const float* input_ptr = input + outer_idx * (reduce_size * outer_dim_stride) + inner_idx;

    for(int i = 0; i < reduce_size; ++i) {
        sum += input_ptr[i * inner_dim_stride];
    }

    output[idx] = sum / reduce_size;
}

torch::Tensor mean_reduce_cuda(torch::Tensor x, int dim) {
    auto sizes = x.sizes().vec();
    const int reduce_size = sizes[dim];
    sizes.erase(sizes.begin() + dim);
    auto output = torch::empty(sizes, x.options());

    const int num_outputs = output.numel();
    const int block_size = 256;
    const int num_blocks = (num_outputs + block_size - 1) / block_size;

    const int inner_stride = dim == x.dim() - 1 ? 1 : x.stride(dim + 1);
    const int outer_stride = dim == 0 ? x.stride(0) : x.size(dim-1) * x.stride(dim-1);

    mean_reduce_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        num_outputs,
        reduce_size,
        inner_stride,
        outer_stride
    );

    return output;
}
"""

mean_reduce_cpp_source = "torch::Tensor mean_reduce_cuda(torch::Tensor x, int dim);"

mean_reduce = load_inline(
    name="mean_reduce",
    cpp_sources=mean_reduce_cpp_source,
    cuda_sources=mean_reduce_source,
    functions=["mean_reduce_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        self.custom_mean = mean_reduce

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_mean.mean_reduce_cuda(x, self.dim)
